function parseCutDecision(cut){
  try{
    const raw=String(cut.notes||'');
    const meta=raw.startsWith('LMOS_CUT:')?JSON.parse(raw.slice(9)):{};
    const rolls=Number(cut.bales||cut.rolls||0),weight=Number(meta.weight||500),sold=Number(meta.sold_rolls||0);
    const costs=['fuel_cost','tractor_cost','mower_cost','rake_cost','baler_cost','labor_cost','machinery_cost','freight_cost','repairs_cost','other_cost'].reduce((sum,k)=>sum+Number(meta[k]||0),0);
    const revenue=sold*Number(meta.sale_price_per_roll||0)+(Number(meta.sale_price_per_ton||0)>0?Math.max(0,(rolls-sold)*weight/1000)*Number(meta.sale_price_per_ton||0):0);
    return {...cut,meta,rolls,weight,sold,stock:Math.max(0,rolls-sold),tons:rolls*weight/1000,costs,revenue,margin:revenue-costs};
  }catch(_e){return {...cut,meta:{},rolls:Number(cut.bales||cut.rolls||0),weight:500,sold:0,stock:Number(cut.bales||cut.rolls||0),tons:Number(cut.total_kg||0)/1000,costs:0,revenue:0,margin:0}}
}
function alfalfaDecisionPage(){
  const cuts=S.cuts.map(parseCutDecision).sort((a,b)=>String(b.cut_date||'').localeCompare(String(a.cut_date||'')));
  const alfalfaLots=S.lots.filter(l=>String(l.crop||'').toLowerCase().includes('alfalfa'));
  const today=new Date();
  const dateOnly=value=>value?new Date(`${String(value).slice(0,10)}T12:00:00`):null;
  const daysSince=value=>{const d=dateOnly(value);return d?Math.max(0,Math.floor((today-d)/86400000)):null};
  const addDays=(value,days)=>{const d=dateOnly(value)||new Date();d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)};
  const latestBy=(rows,key='balance_date')=>[...rows].sort((a,b)=>String(b[key]||'').localeCompare(String(a[key]||'')))[0];
  const latestWeather=latestBy(S.weatherStationObservations||[],'observed_at');
  const forecastRain=(S.weather?.daily?.precipitation_sum||[]).slice(0,4).reduce((s,v)=>s+Number(v||0),0);
  const totalRolls=cuts.reduce((n,c)=>n+c.rolls,0),stock=cuts.reduce((n,c)=>n+c.stock,0),tons=cuts.reduce((n,c)=>n+c.tons,0);
  const costs=cuts.reduce((n,c)=>n+c.costs,0),revenue=cuts.reduce((n,c)=>n+c.revenue,0),margin=revenue-costs;

  const plans=alfalfaLots.map(l=>{
    const lotCuts=cuts.filter(c=>c.lot_id===l.id);
    const last=lotCuts[0]||null;
    const days=daysSince(last?.cut_date);
    const hydric=latestBy((S.hydricDailyBalances||[]).filter(x=>x.lot_id===l.id));
    const profile=(S.hydricProfiles||[]).find(x=>x.lot_id===l.id);
    const analysis=latest(l);
    const irrig=latestBy((S.irrigations||[]).filter(x=>x.lot_id===l.id),'event_date');
    const ha=Number(l.hectares||l.area_ha||0);
    const historicRolls=lotCuts.reduce((s,c)=>s+c.rolls,0);
    const historicHa=lotCuts.reduce((s,c)=>s+Number(c.meta?.hectares||ha||0),0);
    const rollsHa=historicHa?historicRolls/historicHa:0;
    const completedCuts=new Set(lotCuts.map(c=>`${c.meta?.campaign||String(c.cut_date||'').slice(0,4)}-${c.meta?.cut_number||c.cut_date}`)).size;
    const expectedCuts=Number(last?.meta?.expected_cuts_year||10);
    const annualProjection=completedCuts?historicRolls/completedCuts*expectedCuts:0;
    const capacity=Number(profile?.profile_capacity_mm||profile?.total_storage_mm||0);
    const stored=Number(hydric?.water_stored_mm||hydric?.storage_mm||hydric?.estimated_storage_mm||0);
    const occupancy=capacity>0&&stored>0?Math.min(100,stored/capacity*100):null;
    const depletion=Number(hydric?.depletion_pct||hydric?.depletion_fraction*100||0);
    const ndvi=Number(analysis?.ndvi_avg||0);
    let score=0;
    if(days==null) score+=25; else if(days>=35) score+=50; else if(days>=30) score+=38; else if(days>=24) score+=22; else score+=8;
    if(occupancy!=null){if(occupancy<45)score+=35;else if(occupancy<60)score+=22;else if(occupancy<75)score+=10;}
    else if(depletion>0){if(depletion>60)score+=35;else if(depletion>45)score+=22;}
    if(ndvi>0&&ndvi<.50)score+=18;else if(ndvi>0&&ndvi<.62)score+=8;
    if(forecastRain>=15)score-=10;
    score=Math.max(0,Math.min(100,score));
    const status=score>=70?'Prioridad alta':score>=45?'Atención':score>=25?'Seguimiento':'En crecimiento';
    const statusClass=score>=70?'bad':score>=45?'warn':'';
    const targetDays=30;
    const nextCut=last?addDays(last.cut_date,targetDays):null;
    const waterText=occupancy!=null?`${number(occupancy,0)}% del perfil`:depletion?`${number(depletion,0)}% agotado`:'Sin balance';
    const recommendation=score>=70?'Recorrer hoy y definir corte/riego con observación de campo.':score>=45?'Controlar humedad, rebrote y pronóstico durante las próximas 48 h.':score>=25?'Mantener seguimiento; todavía no aparece una urgencia operativa.':'Lote en fase de crecimiento, sin intervención inmediata.';
    return {l,last,days,hydric,profile,analysis,irrig,ha,rollsHa,annualProjection,completedCuts,expectedCuts,occupancy,depletion,ndvi,score,status,statusClass,nextCut,waterText,recommendation};
  }).sort((a,b)=>b.score-a.score||Number(b.days||0)-Number(a.days||0));

  const alerts=[];
  plans.filter(x=>x.score>=70).forEach(x=>alerts.push(`${x.l.name}: prioridad ${number(x.score)}; ${x.recommendation}`));
  plans.filter(x=>x.days!=null&&x.days>=35).forEach(x=>alerts.push(`${x.l.name}: ${x.days} días desde el último corte.`));
  plans.filter(x=>x.occupancy!=null&&x.occupancy<50).forEach(x=>alerts.push(`${x.l.name}: reserva estimada por debajo del 50% del perfil.`));
  cuts.filter(c=>Number(c.meta.humidity||0)>20).slice(0,4).forEach(c=>alerts.push(`${S.lots.find(l=>l.id===c.lot_id)?.name||'Lote'}: humedad de rollo ${number(c.meta.humidity,1)}%; revisar almacenamiento.`));

  const planRows=plans.map(x=>`<tr><td><b>${esc(x.l.name)}</b><small>${hectares(x.ha)}</small></td><td>${x.last?shortDate(x.last.cut_date):'Sin registrar'}<small>${x.days==null?'':`${x.days} días`}</small></td><td>${x.nextCut?shortDate(x.nextCut):'Pendiente'}</td><td>${x.ndvi?number(x.ndvi,2):'—'}</td><td>${esc(x.waterText)}<small>${x.irrig?`Último riego ${shortDate(x.irrig.event_date)}`:'Sin riego registrado'}</small></td><td>${x.rollsHa?`${number(x.rollsHa,1)} rollos/ha`:'—'}<small>${x.completedCuts}/${x.expectedCuts} cortes</small></td><td><span class="pill ${x.statusClass}">${x.status}</span><small>Índice ${number(x.score)}/100</small></td><td><button class="secondary goProduction">Cargar datos</button></td></tr>`).join('');
  const recent=cuts.slice(0,8).map(c=>`<tr><td>${shortDate(c.cut_date)}</td><td><b>${esc(S.lots.find(l=>l.id===c.lot_id)?.name||'Lote')}</b></td><td>${number(c.rolls)} rollos<small>${number(c.tons,1)} t</small></td><td>${number(c.stock)} rollos</td><td>${money(c.costs)}</td><td class="${c.margin>=0?'positive':'negative'}">${money(c.margin)}</td></tr>`).join('');
  const priority=plans[0];
  return `<div class="page-head"><div><p class="eyebrow">CENTRO ALFALFA · V36.5</p><h2>Producción, agua y ciclo de cortes</h2><p class="muted">Integra cortes, rendimiento, balance hídrico, riegos, clima y vigor. Las prioridades son orientativas y deben confirmarse en campo.</p></div><div class="actions"><button class="secondary quickNav" data-page="hydric-intelligence">Abrir riego</button><button class="primary newCut">+ Registrar corte</button></div></div>
  <div class="metrics"><div class="metric"><span>Producción acumulada</span><b>${number(totalRolls)} rollos</b><small>${number(tons,1)} toneladas</small></div><div class="metric"><span>Stock estimado</span><b>${number(stock)} rollos</b><small>producidos menos salidas</small></div><div class="metric"><span>Margen registrado</span><b>${money(margin)}</b><small>Ingresos ${money(revenue)}</small></div><div class="metric"><span>Lluvia próxima 4 días</span><b>${number(forecastRain,1)} mm</b><small>${latestWeather?'Ecowitt + pronóstico':'pronóstico disponible'}</small></div></div>
  <div class="grid2"><div class="panel"><div class="panel-title"><div><h3>Decisión operativa de hoy</h3><p class="muted">Ordenada por ciclo, humedad y vigor.</p></div></div>${priority?`<div class="status"><b>${esc(priority.l.name)} · ${esc(priority.status)}</b><br>${esc(priority.recommendation)}<br><small>Último corte: ${priority.last?`${priority.days} días`:'sin datos'} · Agua: ${esc(priority.waterText)} · NDVI: ${priority.ndvi?number(priority.ndvi,2):'sin datos'}.</small></div>`:'<div class="empty">Creá o marcá lotes con cultivo Alfalfa para iniciar el tablero.</div>'}</div><div class="panel"><h3>Alertas de gestión</h3>${alerts.length?alerts.slice(0,8).map(a=>`<div class="row"><div><b>⚠ ${esc(a)}</b></div></div>`).join(''):'<div class="status">No hay alertas automáticas con los datos actuales.</div>'}</div></div>
  <div class="panel" style="margin-top:18px"><div class="panel-title"><div><h3>Planificador integral por lote</h3><p class="muted">La fecha objetivo usa 30 días como referencia inicial; se ajustará con tus datos reales.</p></div><button class="secondary quickNav" data-page="lots">Preparar lotes</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Lote</th><th>Último corte</th><th>Fecha objetivo</th><th>NDVI</th><th>Estado hídrico</th><th>Rendimiento</th><th>Prioridad</th><th></th></tr></thead><tbody>${planRows||'<tr><td colspan="8" class="empty">No hay lotes de alfalfa configurados.</td></tr>'}</tbody></table></div></div>
  <div class="panel" style="margin-top:18px"><div class="panel-title"><div><h3>Resultado por corte</h3><p class="muted">Producción, stock, costos y margen según los datos cargados.</p></div><button class="secondary goProduction">Ver producción completa</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Fecha</th><th>Lote</th><th>Producción</th><th>Stock</th><th>Costos</th><th>Margen</th></tr></thead><tbody>${recent||'<tr><td colspan="6" class="empty">Todavía no hay cortes registrados.</td></tr>'}</tbody></table></div></div>`;
}
function flightsPage(){
  const analyses=[...S.analyses].sort((a,b)=>String(b.flight_date||'').localeCompare(String(a.flight_date||'')));
  const analysedLots=new Set(analyses.map(a=>a.lot_id)).size;
  const average=analyses.length?analyses.reduce((sum,a)=>sum+Number(a.ndvi_avg||0),0)/analyses.length:0;
  const lowVigor=analyses.filter(a=>Number(a.low_vigor_pct||0)>15).length;
  const cards=analyses.map(a=>{
    const lot=S.lots.find(l=>l.id===a.lot_id);
    const history=analyses.filter(x=>x.lot_id===a.lot_id);
    const position=history.findIndex(x=>x.id===a.id);
    const prior=position>=0?history[position+1]:null;
    const delta=prior?Number(a.ndvi_avg||0)-Number(prior.ndvi_avg||0):null;
    const v=vigor(a.ndvi_avg);
    return `<article class="analysis-card"><div class="panel-title"><div><b>${esc(lot?.name||'Lote sin identificar')}</b><small class="muted">${shortDate(a.flight_date)} · ${hectares(a.hectares||lot?.hectares||0)}</small></div><span class="pill ${v[1]}">${v[0]}</span></div><span>NDVI promedio</span><b class="big">${number(a.ndvi_avg,2)}</b><div class="progress"><i style="width:${Math.max(0,Math.min(100,Number(a.ndvi_avg||0)*100))}%"></i></div><p>NDRE ${number(a.ndre_avg,2)} · Bajo vigor ${number(a.low_vigor_pct,1)}%</p><p class="muted">${delta==null?'Primer análisis del lote':`Cambio vs. vuelo anterior: ${delta>=0?'+':''}${number(delta,2)}`}</p><p>${esc(a.recommendation||'Sin recomendación registrada.')}</p><div class="actions"><button class="secondary makeOrder" data-id="${a.id}">Crear orden T100</button><button class="secondary openFile" data-path="${esc(a.map_file_path||'')}">Abrir mapa</button></div></article>`;
  }).join('');
  return `<div class="page-head"><div><p class="eyebrow">AGRICULTURA DE PRECISIÓN</p><h2>Vuelos y análisis</h2><p class="muted">Historial multiespectral, vigor por lote y generación de órdenes de aplicación.</p></div><button class="primary newAnalysis">+ Importar análisis</button></div><div class="metrics"><div class="metric"><span>Vuelos procesados</span><b>${number(analyses.length)}</b><small>análisis guardados</small></div><div class="metric"><span>Lotes analizados</span><b>${number(analysedLots)}</b><small>de ${number(S.lots.length)} lotes</small></div><div class="metric"><span>NDVI promedio</span><b>${analyses.length?number(average,2):'—'}</b><small>promedio histórico</small></div><div class="metric"><span>Requieren revisión</span><b>${number(lowVigor)}</b><small>más de 15% de bajo vigor</small></div></div><div class="grid3">${cards||'<div class="panel empty"><h3>Todavía no hay vuelos procesados</h3><p>Importá un CSV de zonas para calcular NDVI, NDRE y porcentaje de bajo vigor.</p><button class="primary newAnalysis">Importar primer análisis</button></div>'}</div>`;
}

function ordersPage(){
  const rows=[...S.orders].sort((a,b)=>String(b.order_date||'').localeCompare(String(a.order_date||''))).map(o=>`<tr><td>${shortDate(o.order_date)}</td><td><b>${esc(o.lot_name||S.lots.find(l=>l.id===o.lot_id)?.name||'Lote')}</b></td><td>${esc(o.application_type||'Aplicación')}</td><td>${hectares(o.hectares||0)}</td><td>${esc(o.product||'—')} · ${number(o.dose,2)} ${esc(o.dose_unit||'')}</td><td>${number(o.estimated_product,1)} producto · ${number(o.estimated_batteries)} bat. · ${number(o.estimated_minutes)} min</td><td><span class="pill">${esc(o.status||'Planificada')}</span></td></tr>`).join('');
  return `<div class="page-head"><div><p class="eyebrow">DJI AGRAS T100</p><h2>Órdenes de aplicación</h2><p class="muted">Planificación y seguimiento de aplicaciones vinculadas con cada lote.</p></div><button class="primary newOrder">+ Nueva orden</button></div><div class="panel"><table class="table"><thead><tr><th>Fecha</th><th>Lote</th><th>Trabajo</th><th>Superficie</th><th>Producto</th><th>Estimación</th><th>Estado</th></tr></thead><tbody>${rows||'<tr><td colspan="7" class="muted">No hay órdenes registradas.</td></tr>'}</tbody></table></div>`;
}

function dashboardPage(){
  const company=S.companies.find(c=>c.id===S.companyId);
  const activeLots=S.lots.filter(l=>String(l.status||'Activo').toLowerCase()!=='archivado');
  const hasRealLots=activeLots.length>0;
  const totalSurface=hasRealLots?totalHa():148;
  const cropSummary=hasRealLots?Object.entries(activeLots.reduce((acc,l)=>{const crop=String(l.crop||'Sin cultivo').trim()||'Sin cultivo';acc[crop]=(acc[crop]||0)+Number(l.hectares||l.area_ha||0);return acc},{})).sort((a,b)=>b[1]-a[1]):[['Alfalfa',88],['Trigo',60]];
  const alfalfaHa=cropSummary.filter(([c])=>c.toLowerCase().includes('alfalfa')).reduce((s,[,ha])=>s+ha,0);
  const wheatHa=cropSummary.filter(([c])=>c.toLowerCase().includes('trigo')).reduce((s,[,ha])=>s+ha,0);
  const rolls=S.cuts.reduce((sum,x)=>sum+Number(x.bales||x.rolls||0),0);
  const stock=S.stockMovements.reduce((sum,x)=>{const type=String(x.movement_type||x.type||'').toLowerCase();const qty=Number(x.quantity||x.bales||x.rolls||0);return sum+(type.includes('sal')||type.includes('venta')?-qty:qty)},0)||rolls;
  const pendingOrders=S.orders.filter(x=>String(x.status||'').toLowerCase()!=='completada');
  const pendingTasks=S.dailyFieldTasks.filter(x=>!['completada','cerrada'].includes(String(x.status||'').toLowerCase()));
  const openOpps=S.crmOpportunities.filter(x=>!['Ganada','Perdida'].includes(x.stage));
  const lowVigor=activeLots.filter(l=>latest(l)?.ndvi_avg!=null&&Number(latest(l).ndvi_avg)<.62);
  const w=S.weather?.current;
  const wind=Number(w?.wind_speed_10m||0), temp=Number(w?.temperature_2m||0);
  const weather=w?`${weatherText(w.weather_code)} · ${number(temp,1)} °C · viento ${number(wind)} km/h`:'Clima pendiente de actualización';
  const income=S.movements.filter(x=>String(x.type||x.movement_type||'').toLowerCase().includes('ing')).reduce((a,x)=>a+Number(x.amount||x.income||0),0);
  const expense=S.movements.filter(x=>String(x.type||x.movement_type||'').toLowerCase().includes('egr')).reduce((a,x)=>a+Number(x.amount||x.cost||0),0);
  const droneWindow=!w?'Sin datos':wind<=18?'Apta con control local':'No recomendada por viento';
  const recommendations=[];
  if(!hasRealLots)recommendations.push(['Configuración','Ejecutar la migración 029 para cargar los 13 lotes del gemelo digital.','Alta']);
  if(lowVigor.length)recommendations.push(['Agronomía',`${lowVigor.length} lote(s) presentan NDVI menor a 0,62 y requieren recorrido.`, 'Alta']);
  if(pendingOrders.length)recommendations.push(['Drones',`${pendingOrders.length} orden(es) T100 esperan ejecución o cierre.`, 'Media']);
  if(w&&wind>18)recommendations.push(['Clima','Postergar aplicaciones sensibles hasta que disminuya el viento.','Alta']);
  if(!pendingTasks.length)recommendations.push(['Agenda','No hay tareas de campo pendientes cargadas para hoy.','Informativa']);
  if(!recommendations.length)recommendations.push(['Operación','Sin alertas críticas; mantener recorridas y registros diarios.','Correcto']);
  const equipmentStatus=(name)=>S.equipment.find(e=>String(`${e.name} ${e.brand} ${e.model}`).toLowerCase().includes(name))?.status||'Preparado para registrar';
  const lotsPreview=hasRealLots?activeLots.slice(0,6):[
    {name:'Alfalfa · bloque productivo',crop:'Alfalfa',hectares:88,status:'Base confirmada'},
    {name:'Trigo · campaña actual',crop:'Trigo',hectares:60,status:'Base confirmada'}
  ];
  return `<div class="smart-farm-page">
  <section class="smart-hero"><div><p class="eyebrow">SMART FARM · GEMELO DIGITAL</p><h2>Buenas ${new Date().getHours()<13?'mañanas':new Date().getHours()<20?'tardes':'noches'}, Franco</h2><p>Centro de operaciones de ${esc(company?.name||'La Magdalena')} · Santiago Temple, Córdoba.</p></div><div class="smart-weather"><span>🌦 Condiciones actuales</span><b>${esc(weather)}</b><small>Ventana T100: ${esc(droneWindow)}</small></div></section>
  <section class="smart-kpis"><article><span>Superficie gestionada</span><b>${number(totalSurface)} ha</b><small>${hasRealLots?activeLots.length:13} lotes · gemelo digital</small></article><article><span>Alfalfa</span><b>${number(alfalfaHa)} ha</b><small>${number(rolls)} rollos producidos registrados</small></article><article><span>Trigo</span><b>${number(wheatHa)} ha</b><small>campaña y costos integrados</small></article><article><span>Stock de rollos</span><b>${number(Math.max(0,stock))}</b><small>existencia calculada</small></article></section>
  <section class="smart-grid"><div class="panel smart-map-card"><div class="panel-title"><div><p class="eyebrow">ESTABLECIMIENTO</p><h3>Gemelo digital de La Magdalena</h3></div><button class="secondary goMap">Abrir mapa</button></div><div class="smart-field"><div class="field-label alfalfa-field"><b>88 ha</b><span>Alfalfa · riego por goteo</span></div><div class="field-label wheat-field"><b>60 ha</b><span>Trigo</span></div></div><div class="smart-lot-list">${lotsPreview.map(l=>`<div><span><b>${esc(l.name)}</b><small>${esc(l.crop||'Cultivo')} · ${number(l.hectares||l.area_ha)} ha</small></span><em>${esc(l.status||'Activo')}</em></div>`).join('')}</div></div>
  <div class="smart-side"><div class="panel"><div class="panel-title"><h3>Operación de hoy</h3><span class="pill">${pendingTasks.length+pendingOrders.length}</span></div><div class="smart-status-list"><div><span>🚁 DJI Agras T100</span><b>${esc(equipmentStatus('t100'))}</b><small>${pendingOrders.length} órdenes pendientes</small></div><div><span>🛰 Relevamiento de precisión</span><b>${esc(equipmentStatus('mavic'))}</b><small>${S.analyses.length} análisis cargados</small></div><div><span>🚛 Scania R450</span><b>${esc(equipmentStatus('scania'))}</b><small>${S.trips.length} viajes registrados</small></div><div><span>🤝 CRM</span><b>${openOpps.length} oportunidades</b><small>${S.clients.length} clientes</small></div></div></div><div class="panel"><h3>Acciones rápidas</h3><div class="smart-actions"><button class="primary newOrder">+ Orden T100</button><button class="secondary goProduction">Registrar producción</button><button class="secondary newCrmClient">Nuevo cliente</button><button class="secondary goMap">Ver lotes</button></div></div></div></section>
  <section class="smart-grid"><div class="panel"><div class="panel-title"><div><p class="eyebrow">LM AI OPERATIVA</p><h3>Recomendaciones priorizadas</h3></div><button class="secondary goAi">Consultar LM AI</button></div><div class="smart-recommendations">${recommendations.map(([area,text,level])=>`<article><span>🤖</span><div><b>${esc(area)}</b><p>${esc(text)}</p></div><em class="${level==='Alta'?'bad':level==='Media'?'warn':''}">${esc(level)}</em></article>`).join('')}</div></div><div class="panel"><p class="eyebrow">GESTIÓN ECONÓMICA</p><h3>Resultado acumulado</h3><div class="smart-finance"><div><span>Ingresos</span><b>${money(income)}</b></div><div><span>Egresos</span><b>${money(expense)}</b></div><div><span>Resultado</span><b>${money(income-expense)}</b></div><div><span>Pipeline CRM</span><b>${money(openOpps.reduce((s,o)=>s+Number(o.estimated_amount||0)*Number(o.probability||0)/100,0))}</b></div></div></div></section>
  <p class="smart-note">Los indicadores reales se actualizan con los registros del sistema. Las 148 ha confirmadas se muestran como base del gemelo digital hasta ejecutar la migración inicial.</p></div>`
}
function managementPage(){const income=S.movements.filter(x=>String(x.type||x.movement_type||'').toLowerCase().includes('ing')).reduce((a,x)=>a+Number(x.amount||0),0),expense=S.movements.filter(x=>String(x.type||x.movement_type||'').toLowerCase().includes('egr')).reduce((a,x)=>a+Number(x.amount||0),0),rolls=S.cuts.reduce((a,x)=>a+Number(x.bales||x.rolls||0),0),haDrone=S.analyses.reduce((a,x)=>a+Number(x.hectares||0),0);return `<div class="page-head"><div><p class="eyebrow">DIRECCIÓN Y CONTROL</p><h2>Tablero gerencial</h2><p class="muted">Indicadores productivos, operativos y financieros consolidados.</p></div></div><div class="metrics"><div class="metric"><span>Ingresos</span><b>${money(income)}</b><small>movimientos registrados</small></div><div class="metric"><span>Egresos</span><b>${money(expense)}</b><small>costos registrados</small></div><div class="metric"><span>Resultado</span><b>${money(income-expense)}</b><small>margen acumulado</small></div><div class="metric"><span>Rollos producidos</span><b>${rolls}</b><small>${S.cuts.length} cortes</small></div></div><div class="grid2"><div class="panel"><h3>Operación</h3><div class="row"><b>Superficie gestionada</b><span class="pill">${totalHa()} ha</span></div><div class="row"><b>Hectáreas monitoreadas</b><span class="pill">${haDrone.toFixed(1)} ha</span></div><div class="row"><b>Órdenes T100 activas</b><span class="pill">${S.orders.filter(x=>x.status!=='Completada').length}</span></div><div class="row"><b>Clientes registrados</b><span class="pill">${S.clients.length}</span></div><div class="row"><b>Viajes registrados</b><span class="pill">${S.trips.length}</span></div></div><div class="panel"><h3>Prioridades de gestión</h3>${S.lots.filter(l=>Number(latest(l)?.ndvi_avg||1)<.62).slice(0,5).map(l=>`<div class="row"><div><b>${esc(l.name)}</b><small>Revisar vigor, humedad y nutrición.</small></div><span class="pill warn">Atención</span></div>`).join('')||'<div class="empty">No hay prioridades críticas.</div>'}</div></div>`}
function weatherPage(){const w=S.weather;if(!w)return `<div class="panel empty"><h2>Centro meteorológico</h2><p>No fue posible obtener el pronóstico. Verifique la conexión a internet.</p><button class="primary refreshWeather">Reintentar</button></div>`;const c=w.current,d=w.daily;return `<div class="page-head"><div><p class="eyebrow">CLIMA Y OPERACIONES</p><h2>Centro meteorológico</h2><p class="muted">Santiago Temple · pronóstico operativo de 7 días.</p></div><button class="secondary refreshWeather">Actualizar</button></div><div class="hero"><div class="grid2"><div><p class="eyebrow">CONDICIONES ACTUALES</p><h2>${Number(c.temperature_2m).toFixed(1)} °C · ${weatherText(c.weather_code)}</h2><p>Humedad ${c.relative_humidity_2m}% · Viento ${Number(c.wind_speed_10m).toFixed(0)} km/h</p></div><div class="status" style="background:#ffffff18;color:#fff"><b>Ventana operativa</b><p style="margin:8px 0 0">${Number(c.wind_speed_10m)<=18?'Condiciones compatibles con inspección y vuelo, sujeto a ráfagas locales.':'Viento elevado: postergar vuelos y aplicaciones sensibles.'}</p></div></div></div><div class="grid3">${d.time.map((day,i)=>`<article class="panel"><span class="pill">${new Date(day+'T12:00:00').toLocaleDateString('es-AR',{weekday:'short',day:'2-digit',month:'2-digit'})}</span><h3 style="margin-top:14px">${weatherText(d.weather_code[i])}</h3><p><b>${Math.round(d.temperature_2m_max[i])}°</b> / ${Math.round(d.temperature_2m_min[i])}°</p><p>💧 Lluvia ${Number(d.precipitation_sum[i]||0).toFixed(1)} mm</p><p>☔ Prob. ${Number(d.precipitation_probability_max[i]||0).toFixed(0)}%</p><p>ET₀ ${Number(d.et0_fao_evapotranspiration[i]||0).toFixed(1)} mm</p></article>`).join('')}</div>`}
function aiPage(){return `<div class="page-head"><div><p class="eyebrow">ASISTENTE OPERATIVO</p><h2>LM AI</h2><p class="muted">Consultas sobre clima, riego, lotes, NDVI, producción, clientes, transporte y órdenes T100.</p></div></div><div class="grid2"><div class="panel"><h3>Hacer una consulta</h3><label>Pregunta<textarea id="aiQuestion" placeholder="Ejemplo: ¿Qué lotes debería revisar o regar primero?"></textarea></label><div class="actions"><button id="askAi" class="primary">Consultar</button></div><div id="aiResponse" class="status" style="margin-top:16px">Escriba una pregunta para analizar los datos actuales de la empresa.</div></div><div class="panel"><h3>Consultas sugeridas</h3><div class="row"><div><b>Riego</b><small>¿Qué lotes conviene regar primero?</small></div></div><div class="row"><div><b>Clima</b><small>¿Cómo estará el viento y la lluvia?</small></div></div><div class="row"><div><b>Precisión</b><small>¿Qué lotes tienen NDVI bajo?</small></div></div><div class="row"><div><b>Operación</b><small>¿Cuántas órdenes T100 están pendientes?</small></div></div><div class="row"><div><b>Producción</b><small>¿Cuántos rollos de alfalfa hay registrados?</small></div></div></div></div>`}
function portalPage(){const alerts=S.lots.filter(l=>Number(latest(l)?.ndvi_avg||1)<.62);return `<div class="page-head"><div><p class="eyebrow">VISTA DEL PRODUCTOR</p><h2>Portal de clientes</h2><p class="muted">Resumen seguro de la empresa seleccionada.</p></div></div><div class="client-card"><h2>${esc(S.companies.find(c=>c.id===S.companyId)?.name||'Empresa')}</h2><div class="metrics"><div class="metric"><span>Superficie</span><b>${totalHa()} ha</b></div><div class="metric"><span>Vuelos</span><b>${S.analyses.length}</b></div><div class="metric"><span>Alertas</span><b>${alerts.length}</b></div><div class="metric"><span>Órdenes pendientes</span><b>${S.orders.filter(x=>x.status!=='Completada').length}</b></div></div></div><div class="panel" style="margin-top:18px"><h3>Recomendaciones recientes</h3>${S.analyses.slice(0,6).map(a=>`<div class="row"><div><b>${esc(S.lots.find(l=>l.id===a.lot_id)?.name||'Lote')} · ${a.flight_date}</b><small>${esc(a.recommendation||a.observations||'Sin observaciones')}</small></div><span class="pill">NDVI ${Number(a.ndvi_avg||0).toFixed(2)}</span></div>`).join('')||'<div class="empty">Sin informes todavía.</div>'}</div>`}

function irrigationPage(){
  // La pestaña de riego no recalcula porcentajes: consume el snapshot canónico del motor hídrico.
  const canonical=getHydricState();
  const valves=canonical.rows||[];
  const events=(S.irrigations||[]).slice().sort((a,b)=>String(b.event_date||b.irrigation_date||'').localeCompare(String(a.event_date||a.irrigation_date||'')));
  const totalMm=events.reduce((sum,x)=>sum+Number(x.millimeters||x.mm||0),0);
  const totalHours=events.reduce((sum,x)=>sum+Number(x.hours||0),0);
  const rows=events.map(x=>{const lot=S.lots.find(l=>String(l.id)===String(x.lot_id));const mm=Number(x.millimeters||x.mm||0),hours=Number(x.hours||0),measuredRate=mm>0&&hours>0?mm/hours:null;return `<tr><td>${esc(x.event_date||x.irrigation_date||'—')}</td><td><b>${esc(lot?.name||'Lote sin identificar')}</b></td><td>${number(mm,1)} mm</td><td>${hours>0?`${number(hours,1)} h`:'Sin informar'}</td><td>${measuredRate?`${number(measuredRate,3)} mm/h`:'No calculable'}</td><td>${esc(x.notes||x.observations||'—')}</td></tr>`}).join('');
  const tone=x=>!x.ready?'neutral':String(x.status).startsWith('Regar hoy')?'red':(String(x.status).startsWith('Regar en 24')||String(x.status).startsWith('Vigilar'))?'yellow':'green';
  const valveCards=valves.map(x=>{const area=Number(x.p?.irrigated_area_ha||x.valve?.area_ha||x.lot?.hectares||x.lot?.area_ha||0);const volume=Number(x.application||0)*area*10;const why=explainHydricValve(x.lot?.id||x.canonical?.valveCode);const delta=why?.delta;const change=delta==null?'Primer cálculo':Math.abs(delta)<0.5?'Sin cambio':`${delta>0?'+':''}${number(delta,1)} pts`;return `<button class="irrigation-unified-card ${tone(x)} premiumHydricClock" data-lot="${esc(x.lot?.id||'')}" title="${esc(why?.text||'')}"><div><small>${esc(x.valve?.valve_code||x.p?.valve_code||'Sector')}</small><b>${esc(x.valve?.valve_name||x.p?.valve_name||x.lot?.name||'Válvula')}</b></div><span class="irrigation-unified-pct">${x.occupancy==null?'—':number(x.occupancy,0)+'%'}</span><div class="irrigation-unified-facts"><span><small>Decisión</small><b>${esc(x.status)}</b></span><span><small>Lámina</small><b>${number(x.application||0,1)} mm</b></span><span><small>Volumen</small><b>${volume?number(volume,0)+' m³':'—'}</b></span><span><small>Confianza</small><b>${number(x.confidence||0,0)}%</b></span><span><small>Cambio</small><b>${esc(change)}</b></span><span><small>Motivo</small><b>${esc(why?.reason||'Motor canónico')}</b></span></div><em>Mismo dato que Inicio e Inteligencia →</em></button>`}).join('');
  const syncTime=canonical.updatedAt?new Date(canonical.updatedAt).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'al cargar datos';
  return `<div class="page-head"><div><p class="eyebrow">REGISTROS REALES · FUENTE ÚNICA</p><h2>Riego sincronizado</h2><p class="muted">Los porcentajes, decisiones, láminas y confianza son exactamente los mismos que usa Inicio Premium e Inteligencia Hídrica.</p></div><div class="actions"><span class="pill">Sincronizado ${esc(syncTime)}</span><button class="primary quickNav" data-page="hydric-intelligence">Abrir Centro Inteligente</button></div></div><section class="panel"><div class="panel-title"><div><h3>Estado canónico de todas las válvulas</h3><small class="muted">Una sola fuente de datos; no existen cálculos paralelos en esta pantalla.</small></div><span class="pill">${valves.length}/${S.lots.length} sectores</span></div><div class="irrigation-unified-grid">${valveCards||'<div class="empty">Todavía no hay válvulas configuradas.</div>'}</div></section><div class="metrics"><div class="metric"><span>Riegos registrados</span><b>${events.length}</b><small>eventos conservados</small></div><div class="metric"><span>Lámina acumulada</span><b>${number(totalMm,1)} mm</b><small>suma de registros</small></div><div class="metric"><span>Horas informadas</span><b>${number(totalHours,1)} h</b><small>sin completar datos faltantes</small></div></div><div class="panel"><div class="panel-title"><div><h3>Detalle cronológico</h3><small class="muted">La tasa medida se obtiene únicamente cuando el registro contiene lámina y duración.</small></div></div><div style="overflow:auto"><table class="table"><thead><tr><th>Fecha</th><th>Lote / válvula</th><th>Lámina</th><th>Duración</th><th>Tasa medida</th><th>Observaciones</th></tr></thead><tbody>${rows||'<tr><td colspan="6" class="empty">Todavía no hay riegos registrados.</td></tr>'}</tbody></table></div></div>`;
}
function clientsPage(){return `<div class="page-head"><div><p class="eyebrow">CRM</p><h2>Clientes</h2></div></div><div class="panel">${S.clients.map(c=>`<div class="row"><div><b>${esc(c.name||c.client_name||'Cliente')}</b><small>${esc(c.phone||c.whatsapp||'')} ${esc(c.location||'')}</small></div><span class="pill">${esc(c.status||'Activo')}</span></div>`).join('')||'<div class="empty">Todavía no hay clientes cargados.</div>'}</div>`}
function transportPage(){const km=S.trips.reduce((s,x)=>s+Number(x.kilometers||x.km||0),0),income=S.trips.reduce((s,x)=>s+Number(x.income||x.amount||0),0),cost=S.trips.reduce((s,x)=>s+Number(x.cost||x.total_cost||0),0);return `<div class="page-head"><div><p class="eyebrow">LOGÍSTICA</p><h2>Transporte</h2></div></div><div class="metrics"><div class="metric"><span>Viajes</span><b>${S.trips.length}</b></div><div class="metric"><span>Kilómetros</span><b>${km.toFixed(0)}</b></div><div class="metric"><span>Ingresos</span><b>$ ${income.toLocaleString('es-AR')}</b></div><div class="metric"><span>Margen</span><b>$ ${(income-cost).toLocaleString('es-AR')}</b></div></div><div class="panel"><h3>Últimos viajes</h3>${S.trips.slice(0,10).map(t=>`<div class="row"><div><b>${esc(t.client_name||t.destination||'Viaje')}</b><small>${esc(t.origin||'')} → ${esc(t.destination||'')} · ${Number(t.kilometers||t.km||0)} km</small></div><span class="pill">${esc(t.status||'Registrado')}</span></div>`).join('')||'<div class="empty">Sin viajes registrados.</div>'}</div>`}
function adminPage(){
  const inc=S.movements.filter(x=>(x.type||x.movement_type||'').toLowerCase().includes('ing')).reduce((s,x)=>s+Number(x.amount||0),0),out=S.movements.filter(x=>!(x.type||x.movement_type||'').toLowerCase().includes('ing')).reduce((s,x)=>s+Number(x.amount||0),0);
  const canManage=['Administrador','Superadministrador'].includes(currentRole());
  const memberRows=S.members.map(m=>`<tr><td><b>${esc(m.full_name||m.email||'Usuario')}</b><small>${esc(m.email||'')}</small></td><td>${canManage&&m.user_id!==S.session?.user?.id?`<select class="memberRole" data-id="${m.id}">${['Administrador','Encargado','Operario','Asesor','Cliente'].map(r=>`<option ${m.role===r?'selected':''}>${r}</option>`).join('')}</select>`:`<span class="pill">${esc(m.role)}</span>`}</td><td>${shortDate(m.created_at)}</td><td>${canManage&&m.user_id!==S.session?.user?.id?`<button class="secondary removeMember" data-id="${m.id}">Quitar</button>`:'—'}</td></tr>`).join('');
  const inviteRows=S.invitations.map(i=>`<tr><td><b>${esc(i.full_name||i.email)}</b><small>${esc(i.email)}</small></td><td><span class="pill">${esc(i.role)}</span></td><td><span class="pill ${i.status==='Pendiente'?'warn':''}">${esc(i.status)}</span></td><td>${shortDate(i.expires_at)}</td><td>${canManage&&i.status==='Pendiente'?`<button class="secondary revokeInvite" data-id="${i.id}">Revocar</button>`:'—'}</td></tr>`).join('');
  return `<div class="page-head"><div><p class="eyebrow">GESTIÓN Y SEGURIDAD</p><h2>Administración</h2><p class="muted">Finanzas, usuarios, roles e invitaciones de ${esc(S.companies.find(c=>c.id===S.companyId)?.name||'la empresa')}.</p></div>${canManage?'<button class="primary newInvite">+ Invitar usuario</button>':''}</div><div class="metrics"><div class="metric"><span>Ingresos</span><b>${money(inc)}</b></div><div class="metric"><span>Egresos</span><b>${money(out)}</b></div><div class="metric"><span>Resultado</span><b>${money(inc-out)}</b></div><div class="metric"><span>Usuarios activos</span><b>${S.members.length}</b><small>${S.invitations.filter(i=>i.status==='Pendiente').length} invitaciones pendientes</small></div></div><div class="grid2" style="margin-top:18px"><div class="panel"><p class="eyebrow">MI ACCESO</p><h3>${esc(S.membership?.full_name||S.session?.user?.email||'Usuario')}</h3><div class="row"><span>${esc(S.session?.user?.email||'')}</span><span class="pill">${esc(currentRole())}</span></div><p class="muted">Los permisos también están protegidos por RLS dentro de Supabase.</p></div><div class="panel"><p class="eyebrow">RESUMEN DE PERMISOS</p><h3>${canManage?'Administración habilitada':'Acceso limitado por rol'}</h3><p class="muted">${canManage?'Podés invitar usuarios, cambiar roles y revocar accesos.':'Solo un Administrador puede modificar usuarios y permisos.'}</p></div></div><div class="panel" style="margin-top:18px"><div class="panel-title"><h3>Equipo de la empresa</h3><span class="pill">${S.members.length} miembros</span></div><div style="overflow:auto"><table class="table"><thead><tr><th>Usuario</th><th>Rol</th><th>Alta</th><th></th></tr></thead><tbody>${memberRows||'<tr><td colspan="4">No hay miembros visibles.</td></tr>'}</tbody></table></div></div><div class="panel" style="margin-top:18px"><div class="panel-title"><h3>Invitaciones</h3><span class="pill">${S.invitations.length}</span></div><div style="overflow:auto"><table class="table"><thead><tr><th>Persona</th><th>Rol</th><th>Estado</th><th>Vence</th><th></th></tr></thead><tbody>${inviteRows||'<tr><td colspan="5" class="muted">No hay invitaciones registradas.</td></tr>'}</tbody></table></div><p class="muted">La persona debe crear o ingresar con esta misma dirección de correo. Al iniciar sesión, la invitación se acepta automáticamente.</p></div>`}
function invitationModal(){modal(`<p class="eyebrow">SEGURIDAD SAAS</p><h2>Invitar usuario</h2><form id="inviteForm"><div class="form-grid"><label>Nombre completo<input name="full_name" required></label><label>Correo electrónico<input name="email" type="email" required></label><label>Rol<select name="role"><option>Encargado</option><option>Operario</option><option>Asesor</option><option>Cliente</option><option>Administrador</option></select></label><label>Vigencia<select name="days"><option value="7">7 días</option><option value="14" selected>14 días</option><option value="30">30 días</option></select></label></div><div class="status">La invitación queda registrada. Compartí la URL pública de LA MAGDALENA OS con la persona; debe registrarse usando exactamente este correo.</div><button class="primary">Crear invitación</button><p id="inviteMsg" class="error hidden"></p></form>`);$('#inviteForm').onsubmit=saveInvitation}
async function saveInvitation(e){e.preventDefault();const f=new FormData(e.target),days=Number(f.get('days')||14),row={company_id:S.companyId,email:String(f.get('email')).trim().toLowerCase(),full_name:f.get('full_name'),role:f.get('role'),invited_by:S.session.user.id,expires_at:new Date(Date.now()+days*86400000).toISOString()};const {error}=await sb.from('company_invitations').insert(row);if(error){$('#inviteMsg').textContent=error.message;$('#inviteMsg').classList.remove('hidden');return}$('#modalRoot').innerHTML='';await loadData();render()}
async function updateMemberRole(id,role){const {error}=await sb.from('company_members').update({role}).eq('id',id);if(error)return alert(error.message);await loadData();render()}
async function removeMember(id){if(!confirm('¿Quitar el acceso de este usuario a la empresa?'))return;const {error}=await sb.from('company_members').delete().eq('id',id);if(error)return alert(error.message);await loadData();render()}
async function revokeInvitation(id){const {error}=await sb.from('company_invitations').update({status:'Revocada'}).eq('id',id);if(error)return alert(error.message);await loadData();render()}
function aiAnswer(q){const t=(q||'').toLowerCase(),w=S.weather?.current,d=S.weather?.daily;const low=S.lots.filter(l=>Number(latest(l)?.ndvi_avg||1)<.62),pending=S.orders.filter(x=>x.status!=='Completada'),rain=d?d.precipitation_sum.reduce((a,x)=>a+Number(x||0),0):0;if(!t)return 'Escriba una pregunta sobre riego, clima, lotes, producción, drones, transporte o finanzas.';if(t.includes('regar')||t.includes('riego')){const hs=getHydricSummary(),rows=getHydricRows().filter(x=>x.ready&&x.occupancy!=null).sort((a,b)=>Number(a.occupancy)-Number(b.occupancy));const first=rows[0];if(!first)return 'Todavía faltan datos hídricos suficientes para una recomendación canónica.';const why=explainHydricValve(first.lot?.id||first.canonical?.valveCode);return `${why.text} ${hs.urgent} sector(es) requieren riego hoy, ${hs.watch} deben vigilarse y el promedio disponible es ${hs.average==null?'sin dato':number(hs.average,1)+'%'}. Pronóstico acumulado: ${rain.toFixed(1)} mm.`};if(t.includes('clima')||t.includes('viento')||t.includes('lluvia'))return w?`Ahora: ${Number(w.temperature_2m).toFixed(1)} °C, ${weatherText(w.weather_code)}, viento ${Number(w.wind_speed_10m).toFixed(0)} km/h y humedad ${w.relative_humidity_2m}%. Lluvia acumulada prevista: ${rain.toFixed(1)} mm.`:'No pude obtener el clima en este momento.';if(t.includes('t100')||t.includes('orden'))return `Hay ${pending.length} órdenes T100 pendientes y ${S.orders.length} órdenes totales.`;if(t.includes('ndvi')||t.includes('lote'))return `NDVI promedio ${avgNdvi().toFixed(2)}. ${low.length?`Revisar: ${low.map(x=>x.name).join(', ')}.`:'No hay alertas de vigor.'}`;if(t.includes('rollo')||t.includes('alfalfa'))return `Hay ${S.cuts.length} cortes registrados y ${S.cuts.reduce((a,x)=>a+Number(x.bales||x.rolls||0),0)} rollos acumulados.`;if(t.includes('cliente'))return `La empresa tiene ${S.clients.length} clientes registrados.`;if(t.includes('viaje')||t.includes('scania')||t.includes('transporte')){const ingreso=S.trips.reduce((a,x)=>a+Number(x.income||0),0),costo=S.trips.reduce((a,x)=>a+Number(x.cost||0),0),km=S.trips.reduce((a,x)=>a+Number(x.kilometers||0),0);return `Hay ${S.trips.length} viajes registrados, ${number(km)} km recorridos y un margen acumulado de ${money(ingreso-costo)}.`;}return `Resumen: ${S.lots.length} lotes, ${totalHa()} ha, NDVI ${avgNdvi().toFixed(2)}, ${low.length} alertas y ${pending.length} órdenes T100 pendientes.`}
function saasPage(){const active=S.companies.filter(c=>(c.status||'active')==='active').length,mrr=S.companies.reduce((sum,c)=>sum+Number(c.monthly_price||0),0);return `<div class="page-head"><div><p class="eyebrow">ADMINISTRACIÓN DE LA PLATAFORMA</p><h2>Centro SaaS</h2><p class="muted">Empresas, planes, módulos y estado comercial de cada cliente.</p></div><div class="actions"><button class="primary newCompany">+ Nueva empresa</button></div></div><div class="metrics"><div class="metric"><span>Empresas</span><b>${S.companies.length}</b><small>${active} activas</small></div><div class="metric"><span>MRR estimado</span><b>$ ${mrr.toLocaleString('es-AR')}</b><small>ingreso mensual</small></div><div class="metric"><span>Planes premium</span><b>${S.companies.filter(c=>['premium','enterprise'].includes(c.plan)).length}</b><small>cuentas avanzadas</small></div><div class="metric"><span>Implementación</span><b>${S.companies.filter(c=>(c.onboarding_status||'pending')!=='complete').length}</b><small>clientes pendientes</small></div></div><div class="panel"><div class="panel-title"><h3>Cartera de clientes</h3><span class="pill">Superadministrador</span></div><div style="overflow:auto"><table class="table"><thead><tr><th>Empresa</th><th>Ubicación</th><th>Plan</th><th>Estado</th><th>Precio mensual</th><th>Módulos</th><th></th></tr></thead><tbody>${S.companies.map(c=>{const mods=S.modules.filter(m=>m.company_id===c.id&&m.enabled).length;return `<tr><td><b>${esc(c.name)}</b><small>${esc(c.legal_name||'')}</small></td><td>${esc(c.location||'-')}</td><td>${planLabel(c.plan)}</td><td><span class="pill ${(c.status==='active'||!c.status)?'':'warn'}">${esc(c.status||'active')}</span></td><td>$ ${Number(c.monthly_price||0).toLocaleString('es-AR')}</td><td>${mods}</td><td><button class="secondary editCompany" data-id="${c.id}">Administrar</button></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No hay empresas.</td></tr>'}</tbody></table></div></div><div class="grid3" style="margin-top:18px"><div class="panel"><h3>Planes sugeridos</h3><div class="row"><div><b>Básico</b><small>Lotes, agenda y reportes</small></div></div><div class="row"><div><b>Profesional</b><small>Riego, maquinaria y costos</small></div></div><div class="row"><div><b>Premium</b><small>Precisión, drones y LM AI</small></div></div></div><div class="panel"><h3>Modelo comercial</h3><p class="muted">Suscripción mensual más servicios administrados de drones, mapas e informes agronómicos.</p><div class="status">Cada empresa mantiene sus datos separados mediante políticas RLS.</div></div><div class="panel"><h3>Publicación web</h3><p class="muted">El paquete incluye una guía para desplegar la aplicación y conectar un dominio propio.</p><div class="status">La clave administrativa nunca debe colocarse en el navegador.</div></div></div>`}
function companyModal(company=null){const enabled=new Set(S.modules.filter(m=>m.company_id===company?.id&&m.enabled).map(m=>m.module_key));const all=['dashboard','production','precision','irrigation','drones','lots','clients','crm','sales','purchases','finance','transport','resources','campaigns','admin','ai','portal'];modal(`<p class="eyebrow">V10 ENTERPRISE</p><h2>${company?'Administrar empresa':'Nueva empresa'}</h2><form id="companyForm"><input type="hidden" name="id" value="${company?.id||''}"><div class="form-grid"><label>Nombre comercial<input name="name" value="${esc(company?.name||'')}" required></label><label>Razón social<input name="legal_name" value="${esc(company?.legal_name||'')}"></label><label>Ubicación<input name="location" value="${esc(company?.location||'')}"></label><label>Plan<select name="plan"><option value="basic" ${company?.plan==='basic'?'selected':''}>Básico</option><option value="professional" ${company?.plan==='professional'?'selected':''}>Profesional</option><option value="premium" ${company?.plan==='premium'?'selected':''}>Premium</option><option value="enterprise" ${company?.plan==='enterprise'?'selected':''}>Enterprise</option></select></label><label>Estado<select name="status"><option value="active" ${(company?.status||'active')==='active'?'selected':''}>Activa</option><option value="trial" ${company?.status==='trial'?'selected':''}>Prueba</option><option value="suspended" ${company?.status==='suspended'?'selected':''}>Suspendida</option></select></label><label>Precio mensual<input name="monthly_price" type="number" step="1" value="${Number(company?.monthly_price||0)}"></label><label>Implementación<select name="onboarding_status"><option value="pending" ${(company?.onboarding_status||'pending')==='pending'?'selected':''}>Pendiente</option><option value="in_progress" ${company?.onboarding_status==='in_progress'?'selected':''}>En curso</option><option value="complete" ${company?.onboarding_status==='complete'?'selected':''}>Completa</option></select></label><label>Vencimiento<input name="subscription_expires_at" type="date" value="${company?.subscription_expires_at?.slice?.(0,10)||''}"></label><div class="wide"><b>Módulos habilitados</b><div class="grid3" style="margin-top:10px">${all.map(k=>`<label style="display:flex;grid-template-columns:auto 1fr;align-items:center"><input style="width:auto" type="checkbox" name="module" value="${k}" ${enabled.has(k)||(!company&&['dashboard','lots','clients'].includes(k))?'checked':''}> ${k}</label>`).join('')}</div></div></div><button class="primary">Guardar empresa</button><p id="cm" class="error hidden"></p></form>`);$('#companyForm').onsubmit=saveCompany}
async function saveCompany(e){e.preventDefault();const f=new FormData(e.target),id=f.get('id'),row={name:f.get('name'),legal_name:f.get('legal_name')||null,location:f.get('location')||null,plan:f.get('plan'),status:f.get('status'),monthly_price:Number(f.get('monthly_price')||0),onboarding_status:f.get('onboarding_status'),subscription_expires_at:f.get('subscription_expires_at')||null};try{let companyId=id;if(id){const {error}=await sb.from('companies').update(row).eq('id',id);if(error)throw error}else{row.created_by=S.session.user.id;const {data,error}=await sb.from('companies').insert(row).select().single();if(error)throw error;companyId=data.id}const mods=[...f.getAll('module')];await sb.from('company_modules').delete().eq('company_id',companyId);if(mods.length){const {error}=await sb.from('company_modules').insert(mods.map(module_key=>({company_id:companyId,module_key,enabled:true})));if(error)throw error}$('#modalRoot').innerHTML='';await loadCompanies();await loadData();S.page='saas';render()}catch(err){$('#cm').textContent=err.message;$('#cm').classList.remove('hidden')}}

function bind(){if(S.page==='premium-home'){premiumHomeModule.bind();setTimeout(()=>{document.querySelectorAll('.v65-marker,.v64-sector-map .premiumHydricClock,.v642-card-head.premiumHydricClock').forEach((button)=>{button.onclick=(e)=>{e.preventDefault();e.stopPropagation();let lotId=button.dataset.lot;const idx=button.dataset.v65Index;if(!lotId&&idx!=null){try{const command=button.closest('.v65-command');const valves=JSON.parse(command?.dataset?.valves||'[]');lotId=valves[Number(idx)]?.id}catch{}}if(lotId)laboratoryIntelligentModule.openIntegralTwin(lotId)}})},0)};if(S.page==='campaign-planning')campaignPlanningModule.bind();if(S.page==='command-center')commandCenterModule.bind();if(S.page==='agronomic-assistant')agronomicAssistantModule.bind();if(S.page==='operation-real')operationRealModule.bind();if(S.page==='field-operations')fieldOperationsModule.bind();lotsModule.bind();document.querySelectorAll('.newInvite').forEach(b=>b.onclick=invitationModal);document.querySelectorAll('.memberRole').forEach(x=>x.onchange=()=>updateMemberRole(x.dataset.id,x.value));document.querySelectorAll('.removeMember').forEach(b=>b.onclick=()=>removeMember(b.dataset.id));document.querySelectorAll('.revokeInvite').forEach(b=>b.onclick=()=>revokeInvitation(b.dataset.id));document.querySelectorAll('.refreshWeather').forEach(b=>b.onclick=async()=>{await loadWeather();render()});document.querySelectorAll('.newCompany').forEach(b=>b.onclick=()=>companyModal());document.querySelectorAll('.editCompany').forEach(b=>b.onclick=()=>companyModal(S.companies.find(c=>c.id===b.dataset.id)));productionModule.bind();crmModule.bind();enterpriseControlModule.bind();salesModule.bind();purchasesModule.bind();financeModule.bind();dataSafetyModule.bind();transportModule.bind();resourcesModule.bind();campaignsModule.bind();decisionsModule.bind();establishmentModule.bind();integrationModule.bind();integrationEngineModule.bind();hydricIntelligenceModule.bind();fieldBookModule.bind();precisionCenterModule.bind();laboratoryIntelligentModule.bind();satelliteCenterModule.bind();operationsModule.bind();const content=$('#content');content.onclick=e=>{const newLot=e.target.closest('.newLot');if(newLot){lotsModule.openEditor();return}const editLot=e.target.closest('.editLot');if(editLot){const lot=S.lots.find(item=>item.id===editLot.dataset.id);if(lot)lotsModule.openEditor(lot);return}const lotDetail=e.target.closest('.lotDetail');if(lotDetail){const lot=S.lots.find(item=>item.id===lotDetail.dataset.id);if(lot)lotsModule.openDetails(lot)}};const ask=$('#askAi');if(ask)ask.onclick=()=>{$('#aiResponse').textContent=aiAnswer($('#aiQuestion').value)};document.querySelectorAll('.newAnalysis').forEach(b=>b.onclick=analysisModal);document.querySelectorAll('.newOrder').forEach(b=>b.onclick=()=>orderModal());document.querySelectorAll('.goMap').forEach(b=>b.onclick=()=>{S.page='map';render()});document.querySelectorAll('.goProduction').forEach(b=>b.onclick=()=>{S.page='production';render()});document.querySelectorAll('.goAi').forEach(b=>b.onclick=()=>{S.page='ai';render()});document.querySelectorAll('.goPortal').forEach(b=>b.onclick=()=>{S.page='portal';render()});document.querySelectorAll('.makeOrder').forEach(b=>b.onclick=()=>orderFromAnalysis(b.dataset.id));document.querySelectorAll('.openFile').forEach(b=>b.onclick=()=>openStoredFile(b.dataset.path));document.querySelectorAll('.quickNav').forEach(b=>b.onclick=()=>{S.page=b.dataset.page;document.querySelectorAll('#nav button[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===S.page));render()})}
function modal(html){$('#modalRoot').innerHTML=`<div class="modal-wrap"><div class="modal"><button class="close">×</button>${html}</div></div>`;$('.close').onclick=()=>$('#modalRoot').innerHTML=''}

function analysisModal(){modal(`<p class="eyebrow">ANÁLISIS MULTIESPECTRAL</p><h2>Importar vuelo procesado</h2><form id="analysisForm"><div class="form-grid"><label>Fecha<input name="flight_date" type="date" required></label><label>Lote<select name="lot_id" required><option value="">Seleccionar</option>${S.lots.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></label><label>Superficie (ha)<input name="hectares" type="number" step=".1" required></label><label>CSV de zonas<input name="csv" type="file" accept=".csv,text/csv" required></label><label>Mapa procesado (opcional)<input name="map" type="file" accept="image/*,.pdf,.tif,.tiff"></label><label class="wide">Observaciones<textarea name="observations"></textarea></label></div><p class="status">CSV requerido: zone,ndvi,ndre,area_ha. Se calcularán promedios y porcentaje de bajo vigor automáticamente.</p><button class="primary">Procesar y guardar</button><p id="am" class="error hidden"></p></form>`);$('#analysisForm').onsubmit=saveAnalysis}
function parseCSV(text){const lines=text.trim().split(/\r?\n/).filter(Boolean),headers=lines.shift().split(',').map(x=>x.trim().toLowerCase());const req=['zone','ndvi','ndre','area_ha'];if(req.some(x=>!headers.includes(x)))throw new Error('El CSV debe contener: zone, ndvi, ndre, area_ha');return lines.map(line=>{const vals=line.split(',');const o={};headers.forEach((h,i)=>o[h]=vals[i]?.trim());return{zone:o.zone,ndvi:Number(o.ndvi),ndre:Number(o.ndre),area_ha:Number(o.area_ha)}}).filter(x=>Number.isFinite(x.ndvi)&&Number.isFinite(x.ndre)&&Number.isFinite(x.area_ha))}
async function uploadFile(file,folder){if(!file)return null;const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_'),path=`${S.companyId}/${folder}/${Date.now()}_${safe}`;const {error}=await sb.storage.from('precision-files').upload(path,file,{upsert:false});if(error)throw error;return path}
async function saveAnalysis(e){e.preventDefault();const f=new FormData(e.target),msg=$('#am');try{const csv=f.get('csv'),zones=parseCSV(await csv.text());if(!zones.length)throw new Error('El CSV no tiene filas válidas.');const weighted=(key)=>zones.reduce((s,z)=>s+z[key]*z.area_ha,0)/zones.reduce((s,z)=>s+z.area_ha,0);const vals=k=>zones.map(z=>z[k]);const lowArea=zones.filter(z=>z.ndvi<.55).reduce((s,z)=>s+z.area_ha,0),total=zones.reduce((s,z)=>s+z.area_ha,0),ndvi=weighted('ndvi'),ndre=weighted('ndre');const csvPath=await uploadFile(csv,'csv'),mapPath=await uploadFile(f.get('map')?.size?f.get('map'):null,'maps');const lowPct=total?lowArea/total*100:0;const recommendation=ndvi<.45?'Prioridad alta: inspeccionar estrés hídrico, fallas de implantación o nutrición.':ndvi<.62?'Vigor medio: recorrer sectores de menor índice y verificar humedad/nutrición.':'Vigor general adecuado; mantener seguimiento y comparar con el próximo vuelo.';const row={company_id:S.companyId,lot_id:f.get('lot_id'),flight_date:f.get('flight_date'),hectares:Number(f.get('hectares')),ndvi_avg:ndvi,ndvi_min:Math.min(...vals('ndvi')),ndvi_max:Math.max(...vals('ndvi')),ndre_avg:ndre,ndre_min:Math.min(...vals('ndre')),ndre_max:Math.max(...vals('ndre')),low_vigor_pct:lowPct,zones_count:zones.length,source_file_path:csvPath,map_file_path:mapPath,zones_json:zones,observations:f.get('observations')||null,recommendation,created_by:S.session.user.id};const {error}=await sb.from('precision_analyses').insert(row);if(error)throw error;$('#modalRoot').innerHTML='';await loadData();render()}catch(err){msg.textContent=err.message;msg.classList.remove('hidden')}}
function orderFromAnalysis(id){const a=S.analyses.find(x=>x.id===id),lot=S.lots.find(x=>x.id===a?.lot_id);orderModal({lot_id:lot?.id,hectares:Math.max(.1,Number(a?.hectares||0)*Number(a?.low_vigor_pct||0)/100),notes:`Generada desde análisis ${a?.flight_date}. Bajo vigor: ${Number(a?.low_vigor_pct||0).toFixed(1)}%. ${a?.recommendation||''}`})}
function orderModal(seed={}){modal(`<p class="eyebrow">DJI AGRAS T100</p><h2>Nueva orden</h2><form id="orderForm"><div class="form-grid"><label>Fecha<input name="order_date" type="date" required></label><label>Lote<select name="lot_id" required><option value="">Seleccionar</option>${S.lots.map(l=>`<option value="${l.id}" ${seed.lot_id===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></label><label>Trabajo<input name="application_type" value="Aplicación localizada" required></label><label>Superficie (ha)<input name="hectares" type="number" step=".1" value="${Number(seed.hectares||0).toFixed(1)}" required></label><label>Producto<input name="product" required></label><label>Dosis<input name="dose" type="number" step=".01" required></label><label>Unidad<select name="dose_unit"><option>L/ha</option><option>kg/ha</option></select></label><label>Estado<select name="status"><option>Planificada</option><option>En curso</option><option>Completada</option></select></label><label class="wide">Notas<textarea name="notes">${esc(seed.notes||'')}</textarea></label></div><button class="primary">Guardar orden</button><p id="om" class="error hidden"></p></form>`);$('#orderForm').onsubmit=saveOrder}
async function saveOrder(e){e.preventDefault();const f=new FormData(e.target),lot=S.lots.find(x=>x.id===f.get('lot_id')),ha=Number(f.get('hectares')),dose=Number(f.get('dose')),row={company_id:S.companyId,lot_id:lot.id,lot_name:lot.name,order_date:f.get('order_date'),application_type:f.get('application_type'),hectares:ha,product:f.get('product'),dose,dose_unit:f.get('dose_unit'),estimated_product:ha*dose,estimated_batteries:Math.ceil(ha/18),estimated_minutes:Math.round(ha*4.5),status:f.get('status'),notes:f.get('notes')||null};const {error}=await sb.from('precision_orders').insert(row);if(error){$('#om').textContent=error.message;$('#om').classList.remove('hidden');return}$('#modalRoot').innerHTML='';await loadData();render()}
async function openStoredFile(path){if(!path)return alert('Este análisis no tiene mapa cargado.');const {data,error}=await sb.storage.from('precision-files').createSignedUrl(path,300);if(error)return alert(error.message);window.open(data.signedUrl,'_blank')}
